    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        constructorStrategy = checkNotNull(ruleViolationFileNameStrategy);
        strategyProvidedToConstructor = true;
    }

    @Override
    public void initialize(Properties properties) {
        boolean creationAllowed = Boolean.parseBoolean(properties.getProperty(
                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        boolean updateAllowed = Boolean.parseBoolean(properties.getProperty(
                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        Integrity configuredIntegrity = integrityFrom(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        RuleViolationFileNameStrategy configuredStrategy = strategyFrom(properties);
        String configuredFileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
        boolean configuredNamesAreDeterministic = strategyProvidedToConstructor
                || !FILE_NAMES_RANDOM.equals(configuredFileNames);
        if (configuredIntegrity == Integrity.REPAIR && !updateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires updating the violation store (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        File requestedFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        StoreState state = getStoreState(requestedFolder);
        synchronized (state.lock) {
            File folder = prepareStoreFolder(requestedFolder, creationAllowed);
            // Integrity helpers resolve candidate names relative to this folder before initialization completes.
            storeFolder = folder;
            File indexFile = new File(folder, STORED_RULES_FILE_NAME);
            boolean indexExists = Files.exists(indexFile.toPath(), LinkOption.NOFOLLOW_LINKS)
                    || Files.isSymbolicLink(indexFile.toPath());

            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), indexFile.getAbsolutePath());

            FileSyncedProperties rules;
            if (!indexExists) {
                if (!creationAllowed) {
                    throw missingIndex();
                }
                rules = FileSyncedProperties.empty(indexFile);
                if (configuredIntegrity == Integrity.FAIL) {
                    IntegrityReport report = inspect(rules, folder, indexFile,
                            configuredStrategy, configuredNamesAreDeterministic);
                    if (!report.isClean()) {
                        throw new StoreInitializationFailedException(report.message(folder));
                    }
                    rules.createFile();
                } else {
                    rules.createFile();
                }
            } else {
                if (!Files.isRegularFile(indexFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
                    throw new StoreInitializationFailedException(String.format(
                            "The violation store index must be a regular file directly in the store folder: %s",
                            indexFile.getAbsolutePath()));
                }
                rules = state.storedRules == null ? FileSyncedProperties.load(indexFile) : state.storedRules;
                if (configuredIntegrity != Integrity.IGNORE) {
                    IntegrityReport report = inspect(rules, folder, indexFile,
                            configuredStrategy, configuredNamesAreDeterministic);
                    if (configuredIntegrity == Integrity.FAIL && !report.isClean()) {
                        throw new StoreInitializationFailedException(report.message(folder));
                    }
                    if (configuredIntegrity == Integrity.REPAIR) {
                        repair(report, rules, folder, indexFile);
                    }
                }
            }

            state.storedRules = rules;
            storeFolder = folder;
            storeState = state;
            storedRules = rules;
            storeUpdateAllowed = updateAllowed;
            integrity = configuredIntegrity;
            ruleViolationFileNameStrategy = configuredStrategy;
        }
    }

    private static StoreState getStoreState(File requestedFolder) {
        try {
            File index = new File(requestedFolder, STORED_RULES_FILE_NAME);
            String key = index.getCanonicalPath();
            return STORE_STATES_BY_PATH.computeIfAbsent(key, ignored -> new StoreState());
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static File prepareStoreFolder(File requestedFolder, boolean creationAllowed) {
        Path path = requestedFolder.toPath();
        try {
            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                if (!creationAllowed) {
                    throw missingIndex();
                }
                Files.createDirectories(path);
            }
            if (!Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "The violation store path is not a directory: %s", requestedFolder.getAbsolutePath()));
            }
            return path.toRealPath().toFile();
        } catch (StoreInitializationFailedException e) {
            throw e;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static StoreInitializationFailedException missingIndex() {
        return new StoreInitializationFailedException(String.format(
                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
    }

    private RuleViolationFileNameStrategy strategyFrom(Properties properties) {
        if (strategyProvidedToConstructor) {
            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            return constructorStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
        if (FILE_NAMES_RANDOM.equals(configured)) {
            return randomFileNameStrategy();
        }
        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
            return this::descriptionFileName;
        }
        try {
            Class<?> strategyType = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)
                    || !Modifier.isPublic(strategyType.getModifiers())) {
                throw new IllegalArgumentException("type is not a public RuleViolationFileNameStrategy");
            }
            Constructor<?> constructor = strategyType.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException
                 | InvocationTargetException | ClassCastException | SecurityException e) {
                 | InvocationTargetException | ClassCastException | SecurityException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate RuleViolationFileNameStrategy configured by %s='%s'; it must be a public class with a public no-argument constructor",
                    FILE_NAMES_PROPERTY_NAME, configured), e);
        } catch (IllegalArgumentException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Configured %s='%s' is not a public RuleViolationFileNameStrategy with a public no-argument constructor",
                    FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    private static Integrity integrityFrom(String configured) {
        if (INTEGRITY_REPAIR.equals(configured)) {
            return Integrity.REPAIR;
        }
        if (INTEGRITY_FAIL.equals(configured)) {
            return Integrity.FAIL;
        }
        if (INTEGRITY_IGNORE.equals(configured)) {
            return Integrity.IGNORE;
        }
        throw new StoreInitializationFailedException(String.format(
                "Unsupported value for %s='%s'; accepted values are %s",
                INTEGRITY_PROPERTY_NAME, configured, Arrays.toString(INTEGRITY_VALUES)));
    }

    private RuleViolationFileNameStrategy randomFileNameStrategy() {
        return ignored -> UUID.randomUUID().toString();
    }

    private String descriptionFileName(String description) {
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        String word = "rule";
        while (matcher.find()) {
            String candidate = matcher.group();
            if (candidate.length() >= 4 && candidate.length() <= 120) {
                word = candidate;
            }
        }
        return word + "-" + shortDescriptionHash(description);
    }

    private static String shortDescriptionHash(String description) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                result.append(String.format("%02x", digest[i] & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storeState.lock) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        synchronized (storeState.lock) {
            String description = ensureUnixLineBreaks(rule.getDescription());
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && integrity == Integrity.REPAIR) {
                forgetRuleWithNoViolations(description, existingFileName);
                return;
            }

            Path target;
            boolean newEntry = existingFileName == null;
            if (newEntry) {
                String fileName = createFileNameForNewRule(description);
                target = newDestination(fileName);
                rejectIfAlreadyOccupied(target, fileName);
                writeAtomically(target, encodeViolations(violations), false);
                storedRules.setProperty(description, fileName);
                try {
                    storedRules.syncFileSystem();
                } catch (RuntimeException e) {
                    storedRules.remove(description);
                    deleteQuietly(target);
                    throw e;
                }
            } else {
                target = existingEntryTarget(existingFileName);
                writeAtomically(target, encodeViolations(violations), true);
            }
        }
    }

    private String createFileNameForNewRule(String description) {
        String result;
        try {
            result = ruleViolationFileNameStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreUpdateFailedException(e);
        }
        validateFileName(result, false);
        return result;
    }

    private void validateFileName(String fileName, boolean initialization) {
        if (fileName == null || fileName.trim().isEmpty()) {
            String message = "RuleViolationFileNameStrategy did not provide a file name";
            if (initialization) {
                throw new StoreInitializationFailedException(message);
            }
            throw new StoreUpdateFailedException(message);
        }
    }

    private Path newDestination(String fileName) {
        Path destination = safeDirectPath(fileName);
        if (destination == null || destination.equals(storeFolder.toPath().resolve(STORED_RULES_FILE_NAME))) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' is not a safe file directly in the store folder", fileName));
        }
        return destination;
    }

    private void rejectIfAlreadyOccupied(Path destination, String fileName) {
        if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(destination)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule in '%s': the file name is already occupied", fileName));
        }
        for (Map.Entry<String, String> entry : storedRules.entries()) {
            Path recorded = safeDirectPath(entry.getValue());
            if (fileName.equals(entry.getValue()) || destination.equals(recorded)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule in '%s': the file name is already recorded by another rule", fileName));
            }
        }
    }

    private Path existingEntryTarget(String fileName) {
        FileResolution resolution = resolve(storeFolder, fileName);
        if (resolution.valid) {
            rejectIfIndex(resolution.resolvedPath);
            return resolution.resolvedPath;
        }
        if (resolution.missing && resolution.recordedPath != null
                && resolution.recordedPath.getParent().equals(storeFolder.toPath().toAbsolutePath().normalize())
                && !Files.isSymbolicLink(resolution.recordedPath)
                && !resolution.recordedPath.equals(storeFolder.toPath().resolve(STORED_RULES_FILE_NAME))) {
            return resolution.recordedPath;
        }
        throw new StoreUpdateFailedException(String.format(
                "Cannot update rule violation file '%s': its recorded path is not a safe file in the store folder",
                fileName));
    }

    private void rejectIfIndex(Path path) {
        try {
            if (Files.isSameFile(path, new File(storeFolder, STORED_RULES_FILE_NAME).toPath())) {
                throw new StoreUpdateFailedException("A rule violation file must not be the stored.rules index");
            }
        } catch (IOException e) {
            if (path.toAbsolutePath().normalize().equals(new File(storeFolder, STORED_RULES_FILE_NAME).toPath().toAbsolutePath().normalize())) {
                throw new StoreUpdateFailedException("A rule violation file must not be the stored.rules index");
            }
        }
    }

    private void forgetRuleWithNoViolations(String description, String fileName) {
        if (fileName == null) {
            return;
        }
        FileResolution resolution = resolve(storeFolder, fileName);
        if (!resolution.valid) {
            storedRules.remove(description);
            try {
                storedRules.syncFileSystem();
            } catch (RuntimeException e) {
                storedRules.setProperty(description, fileName);
                throw e;
            }
            return;
        }

        boolean shared = false;
        for (Map.Entry<String, String> entry : storedRules.entries()) {
            if (!description.equals(entry.getKey()) && sameResolution(resolution, resolve(storeFolder, entry.getValue()))) {
                shared = true;
                break;
            }
        }
        byte[] oldContents = null;
        String linkTarget = null;
        if (!shared) {
            try {
                oldContents = Files.readAllBytes(resolution.resolvedPath);
                oldContents = Files.readAllBytes(resolution.resolvedPath);
                if (Files.isSymbolicLink(resolution.recordedPath)) {
                    linkTarget = Files.readSymbolicLink(resolution.recordedPath).toString();
                }
                deleteResolvedFile(resolution);
            } catch (IOException e) {
                if (oldContents != null) {
                    restoreResolvedFile(resolution, oldContents, linkTarget);
                }
                throw new StoreUpdateFailedException(e);
            }
        }

        storedRules.remove(description);
        try {
            storedRules.syncFileSystem();
        } catch (RuntimeException e) {
            storedRules.setProperty(description, fileName);
            if (!shared && oldContents != null) {
                restoreResolvedFile(resolution, oldContents, linkTarget);
            }
            throw e;
        }
    }

    private void deleteResolvedFile(FileResolution resolution) throws IOException {
        rejectIfIndex(resolution.resolvedPath);
        Files.delete(resolution.resolvedPath);
        if (!resolution.recordedPath.equals(resolution.resolvedPath) && Files.exists(resolution.recordedPath, LinkOption.NOFOLLOW_LINKS)) {
            Files.delete(resolution.recordedPath);
        }
    }

    private void restoreResolvedFile(FileResolution resolution, byte[] contents, String linkTarget) {
        try {
            Files.write(resolution.resolvedPath, contents);
            if (linkTarget != null && !Files.exists(resolution.recordedPath, LinkOption.NOFOLLOW_LINKS)) {
                Files.createSymbolicLink(resolution.recordedPath, Paths.get(linkTarget));
            }
        } catch (IOException ignored) {
            log.warn("Could not restore a violation file after an unsuccessful store update at {}", resolution.resolvedPath);
        }
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storeState.lock) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            FileResolution resolution = resolve(storeFolder, ruleDetailsFileName);
            if (!resolution.valid) {
                throw new StoreReadException(new IOException("Invalid stored violation file: " + ruleDetailsFileName));
            }
            List<String> result = readLines(resolution.resolvedPath);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(Path ruleDetailsFile) {
        String violationsText = readStoreFile(ruleDetailsFile);
        if (violationsText.matches("(?:\\r\\n|\\n|\\r)*")) {
            return Collections.emptyList();
        }
        String normalizedLineBreaks = SplitterSupport.normalizeCarriageReturnLineBreaks(violationsText);
        return SplitterSupport.splitOnUnescapedLineBreaks(normalizedLineBreaks).stream()
                .map(this::unescape)
                .filter(line -> !line.isEmpty())
                .collect(toList());
    }

    private String readStoreFile(Path file) {
        try {
            return new String(toByteArray(file.toFile()), UTF_8);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private byte[] encodeViolations(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        return builder.toString().getBytes(UTF_8);
    }

    private String escape(String violation) {
        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
    }

    private IntegrityReport inspect(FileSyncedProperties rules, File folder, File indexFile,
                                   RuleViolationFileNameStrategy strategy, boolean namesAreDeterministic) {
        List<StoredEntry> entries = new ArrayList<>();
        for (Map.Entry<String, String> entry : rules.entries()) {
            String expected = null;
            if (namesAreDeterministic) {
                try {
                    expected = strategy.createRuleFileName(entry.getKey());
                } catch (RuntimeException e) {
                    throw new StoreInitializationFailedException(e);
                }
                validateFileName(expected, true);
            }
            FileResolution resolution = resolve(folder, entry.getValue());
            boolean resolved = resolution.valid && readLines(resolution.resolvedPath).isEmpty();
            entries.add(new StoredEntry(entry.getKey(), entry.getValue(), expected, resolution, resolved));
        }

        Map<FileIdentity, List<StoredEntry>> byFile = new HashMap<>();
        for (StoredEntry entry : entries) {
            byFile.computeIfAbsent(entry.resolution.identity, ignored -> new ArrayList<>()).add(entry);
        }
        Map<String, List<StoredEntry>> byDerivedName = new HashMap<>();
        for (StoredEntry entry : entries) {
            if (entry.expectedName != null) {
                byDerivedName.computeIfAbsent(entry.expectedName, ignored -> new ArrayList<>()).add(entry);
            }
        }

        IntegrityReport result = new IntegrityReport();
        for (StoredEntry entry : entries) {
            entry.shared = byFile.get(entry.resolution.identity).size() > 1;
            entry.broken = !entry.resolution.valid;
            entry.misplaced = entry.expectedName != null && !entry.recordedName.equals(entry.expectedName);
            entry.colliding = entry.expectedName != null && byDerivedName.get(entry.expectedName).size() > 1;
            entry.occupied = entry.misplaced && isOccupiedDerivedName(entry, entries, folder);

            if (entry.broken) {
                result.broken.add(entry);
            }
            if (entry.resolved) {
                result.resolved.add(entry);
            }
            if (entry.shared) {
                result.shared.add(entry);
            }
            if (entry.misplaced) {
                result.misplaced.add(entry);
            }
            if (entry.colliding) {
                result.colliding.add(entry);
            }
            if (entry.occupied) {
                result.occupied.add(entry);
            }
        }

        Set<FileIdentity> ownedFiles = entries.stream()
                .filter(entry -> entry.resolution.valid)
                .map(entry -> entry.resolution.identity)
                .collect(java.util.stream.Collectors.toSet());
        File[] files = folder.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.getName().equals(indexFile.getName())) {
                    continue;
                }
                Path path = file.toPath();
                if (Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
                    FileIdentity identity = FileIdentity.forExisting(path);
                    if (!ownedFiles.contains(identity)) {
                        result.unownedFiles.add(file.getName());
                    }
                }
            }
        }
        Collections.sort(result.unownedFiles);
        return result;
    }

    private boolean isOccupiedDerivedName(StoredEntry entry, List<StoredEntry> entries, File folder) {
        Path derived = safeDirectPath(entry.expectedName);
        if (derived == null || derived.equals(new File(folder, STORED_RULES_FILE_NAME).toPath().toAbsolutePath().normalize())) {
            return true;
        }
        if (Files.exists(derived, LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(derived)) {
            return true;
        }
        for (StoredEntry other : entries) {
            if (other != entry && (entry.expectedName.equals(other.recordedName)
                    || derived.equals(safeDirectPath(other.recordedName)))) {
                return true;
            }
        }
        return false;
    }

    private void repair(IntegrityReport report, FileSyncedProperties rules, File folder, File indexFile) {
        boolean changed = false;
        for (StoredEntry entry : report.entriesToRepair()) {
            if (entry.shared) {
                continue;
