+            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                if (!creationAllowed) {
+                    throw missingIndex(new File(requestedFolder, STORED_RULES_FILE_NAME));
+                }
+                Files.createDirectories(path);
