+    private void forgetRuleWithNoViolations(String description, String fileName) {
+        if (fileName == null) {
+            return;
+        }
+        FileResolution resolution = resolve(storeFolder, fileName);
+        if (!resolution.valid) {
+            storedRules.remove(description);
+            storedRules.syncFileSystem();
+            return;
+        }
