+    private void repair(IntegrityReport report, FileSyncedProperties rules, File folder, File indexFile) {
+        boolean changed = false;
+        for (StoredEntry entry : report.entriesToRepair()) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                rules.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                try {
+                    deleteResolvedFile(entry.resolution);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                rules.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveToDerivedName(entry, folder);
+                rules.setProperty(entry.description, entry.expectedName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            rules.syncFileSystem();
+        }
+    }
