+            }
+            Path path = Paths.get(fileName);
+            Path normalized = (path.isAbsolute() ? path : folder.resolve(path)).normalize().toAbsolutePath();
+            if (!normalized.startsWith(folder) || !folder.equals(normalized.getParent())) {
+                return null;
+            }
+            return normalized;
+        } catch (InvalidPathException e) {
+            return null;
+        }
+    }
+
+    private static Path safeDirectPath(File folder, String fileName) {
+        try {
+            Path folderPath = folder.toPath().toAbsolutePath().normalize();
+            Path path = Paths.get(fileName);
+            Path normalized = (path.isAbsolute() ? path : folderPath.resolve(path)).normalize().toAbsolutePath();
+            return normalized.startsWith(folderPath) && folderPath.equals(normalized.getParent()) ? normalized : null;
